extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale basket.tscn deve avviarsi correttamente"):
		return
	var label := find_by_class(main, "Label") as Label
	if not check("label", label != null, "Il nodo Label deve essere presente nel cesto"):
		return
	await wait_frames(2)
	var p_name = get_prop(main, "player_name", "Cesto")
	var lives = get_prop(main, "lives", 3)
	var speed = get_prop(main, "speed", 350.0)
	var expected := "%s | Vite: %d | Vel: %.1f" % [p_name, lives, speed]
	check("initial_text", label.text == expected, "All'avvio il Label deve mostrare '%s', ma mostra '%s'" % [expected, label.text])
	if not check("has_set_speed", has_function(main, "set_speed"), "Lo script basket.gd deve possedere la funzione set_speed(new_speed: float)"):
		return
	call_if_exists(main, "set_speed", [420.5])
	var expected_updated := "%s | Vite: %d | Vel: %.1f" % [p_name, lives, 420.5]
	check("updated_speed", label.text == expected_updated, "Dopo set_speed(420.5) il Label deve mostrare '%s', ma mostra '%s'" % [expected_updated, label.text])
	call_if_exists(main, "set_speed", [200.0])
	var expected_200 := "%s | Vite: %d | Vel: %.1f" % [p_name, lives, 200.0]
	check("integer_speed", label.text == expected_200, "Con velocità 200.0 il Label deve mostrare '%s', ma mostra '%s'" % [expected_200, label.text])
